use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let arr1 = input.as_array().unwrap();
    let arr2 = input.as_array().unwrap();
    let mut result = Vec::new();
    let mut i = 0;
    let mut j = 0;

    while i < arr1.len() && j < arr2.len() {
        if arr1[i].is_i64() && arr2[j].is_i64() {
            result.push(arr1[i].as_i64().unwrap() + arr2[j].as_i64().unwrap());
            i += 1;
            j += 1;
        } else if arr1[i].is_i64() {
            result.push(arr1[i].as_i64().unwrap());
            i += 1;
        } else if arr2[j].is_i64() {
            result.push(arr2[j].as_i64().unwrap());
            j += 1;
        } else {
            break;
        }
    }

    if i < arr1.len() {
        result.extend(arr1[i..].iter().cloned());
    } else if j < arr2.len() {
        result.extend(arr2[j..].iter().cloned());
    }

    Value::Array(result)
}
